curl -s -X POST "https://slack.com/api/conversations.list" -H "Authorization: Bearer <TOKEN>" --data "types=public_channel" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print(d); sys.exit(1)
for c in d['channels']:
    if 'launch' in c['name'].lower() or 'prep' in c['name'].lower():
        print(c['id'], c['name'], c.get('topic',''))
"

